import {loadDesign,translator,esc,icon,bindPortability,categoryMeta} from '../controller.js';
const params=new URLSearchParams(location.search),language=params.get('lang')==='en'?'en':'zh',category=categoryMeta[params.get('category')]?params.get('category'):'models',state=params.get('state')||'file',outcome=params.get('outcome')==='unknown'?'unknown':'success';
const {copy,fixture}=await loadDesign(),t=translator(copy,language),app=document.querySelector('#app');
document.documentElement.lang=language;
const categories=['models','plans','items','growth'],states=['export','file','decrypt','preview','confirm','blocked','missingkey','fields','mismatch','wrongpass','stale','unknown','success'];
const stepStates=[['export','prototype.step.export'],['file','prototype.step.file'],['preview','prototype.step.preview'],['unknown','prototype.step.result']];
const url=(changes={})=>{const q=new URLSearchParams({lang:language,category,state,outcome});Object.entries(changes).forEach(([k,v])=>q.set(k,v));return `?${q}`};
app.innerHTML=`<div class="cr313-prototype"><header class="prototype-head"><div><p class="eyebrow">${esc(t('prototype.eyebrow'))}</p><h1>${esc(t('prototype.title'))}</h1><p>${esc(t('prototype.desc'))}</p></div><a class="btn primary" href="../formal/?page=${categoryMeta[category].page==='growth'?'operations':categoryMeta[category].page}&category=${category}&portState=${state}&lang=${language}">${esc(t('prototype.formal'))}${icon('arrow')}</a></header><div class="prototype-grid"><aside class="prototype-sidebar" aria-label="${esc(t('demo.title'))}"><div><h2>${esc(t('demo.title'))}</h2><p>${esc(t('demo.help'))}</p><label class="field"><span>Category</span><select data-demo-category>${categories.map(value=>`<option value="${value}" ${value===category?'selected':''}>${esc(t(categoryMeta[value].name))}</option>`).join('')}</select></label><label class="field"><span>State</span><select data-demo-state>${states.map(value=>`<option value="${value}" ${value===state?'selected':''}>${value}</option>`).join('')}</select></label><a class="btn quiet" href="${url({lang:language==='zh'?'en':'zh'})}">${language==='zh'?'English':'中文'}</a></div><nav class="prototype-steps">${stepStates.map(([value,key])=>`<button class="btn ${value===state?'selected':''}" data-step="${value}">${esc(t(key))}</button>`).join('')}</nav></aside><section class="prototype-stage" aria-labelledby="stage-title"><header><p class="eyebrow">${esc(t(categoryMeta[category].name))}</p><h2 id="stage-title">${esc(t('portability.actionsLabel'))}</h2></header><div id="prototype-dialog-host"></div></section></div></div>`;
const host=document.querySelector('#prototype-dialog-host');bindPortability({host,category,state,t,data:fixture,inline:true,outcome});
document.querySelector('[data-demo-category]').addEventListener('change',e=>location.href=url({category:e.target.value}));
document.querySelector('[data-demo-state]').addEventListener('change',e=>location.href=url({state:e.target.value}));
document.querySelectorAll('[data-step]').forEach(button=>button.addEventListener('click',()=>location.href=url({state:button.dataset.step})));
app.setAttribute('aria-busy','false');
